[ExtensionOf(classStr(CustVendSumForPaym))]
final class METCustVendSumForPaym_Extension
{
    
    private boolean             metFromAutomation;
    private container           metPackedFileFormatParams;
    private LedgerJournalId     metAutomationJournalId;

}

Method.Source:
    /// <summary>
    /// CoC extension
    /// </summary>
    protected void updateQuery()
    {
        if(this.metFromAutomation && this.metAutomationJournalId)
        {
            // 'ledgerJournalId' is unpacked and overwritten with a blank value.
            // Ensure value is repopulated before query is updated.
            this.ledgerJournalId = this.metAutomationJournalId;
        }

        next updateQuery();
    }

    /// <summary>
    /// CoC extension
    /// </summary>
    void initCustVendOutPaym()
    {
        next initCustVendOutPaym();
        custVendOutPaym.metParmFromAutomation(metFromAutomation);      
      
        if(this is CustSumForPaym)
        {
            if(conLen(metPackedFileFormatParams))
            {
                custVendOutPaym.unpack(metPackedFileFormatParams);
            }
        }   

    }

/// <summary>
/// CoC extension
/// </summary>
/// <returns>identifierName</returns>
public identifierName lastValueElementName()
{
    IdentifierName ret = next lastValueElementName();
    if(this.metFromAutomation)
    {
        ret = '';
    }
    return ret;        
}

public LedgerJournalId metParmAutomationJournalId(LedgerJournalId _metAutomationJournalId = metAutomationJournalId)
{
    metAutomationJournalId = _metAutomationJournalId;
    return metAutomationJournalId;
}

public container metParmPackedFileFormatParams(container _metPackedFileFormatParams = metPackedFileFormatParams)
{
    metPackedFileFormatParams = _metPackedFileFormatParams;
    return metPackedFileFormatParams;
}

/// <summary>
/// parmfromAutomation
/// </summary>
/// <param name = "_fromAutomation">_fromAutomation</param>
/// <returns>fromAutomation</returns>
public boolean metParmFromAutomation(boolean _metFromAutomation = metFromAutomation)
{
    metFromAutomation = _metFromAutomation;
    return metFromAutomation;
}
